#include <stdio.h>

/* Part 1: Grundy numbers via mex for the subtraction game "take 1-3".
   grundy[n] = mex { grundy[n-1], grundy[n-2], grundy[n-3] } */
int sub_grundy[21];

/* Part 2: brute-force win/loss for real 3-heap Nim up to 8 stones. */
int win[9][9][9];
int computed[9][9][9];

int nim_win(int a, int b, int c) {
    if (a + b + c == 0) return 0;   /* no move available: previous player took the last stone and won */
    if (computed[a][b][c]) return win[a][b][c];
    computed[a][b][c] = 1;
    int result = 0;
    for (int take = 1; take <= a && !result; take++) if (!nim_win(a - take, b, c)) result = 1;
    for (int take = 1; take <= b && !result; take++) if (!nim_win(a, b - take, c)) result = 1;
    for (int take = 1; take <= c && !result; take++) if (!nim_win(a, b, c - take)) result = 1;
    win[a][b][c] = result;
    return result;
}

int main() {
    for (int i = 0; i < 9; i++)
        for (int j = 0; j < 9; j++)
            for (int k = 0; k < 9; k++) { win[i][j][k] = 0; computed[i][j][k] = 0; }

    /* mex demo on the subtraction game */
    sub_grundy[0] = 0;
    for (int n = 1; n <= 20; n++) {
        int seen[4] = {0, 0, 0, 0};
        for (int t = 1; t <= 3 && t <= n; t++) {
            int g = sub_grundy[n - t];
            if (g < 4) seen[g] = 1;
        }
        int mex = 0;
        while (mex < 4 && seen[mex]) mex++;
        sub_grundy[n] = mex;
    }
    printf("subtraction game (take 1-3), grundy numbers:\n  n: ");
    for (int n = 0; n <= 12; n++) printf("%2d ", n);
    printf("\n  g: ");
    for (int n = 0; n <= 12; n++) printf("%2d ", sub_grundy[n]);
    printf("\n  pattern: n mod 4 - positions with g=0 (multiples of 4) are lost\n\n");

    /* verify Bouton over all 729 positions */
    int checked = 0, agree = 1, losing = 0;
    for (int a = 0; a < 9; a++) {
        for (int b = 0; b < 9; b++) {
            for (int c = 0; c < 9; c++) {
                int by_search = nim_win(a, b, c);
                int by_xor = ((a ^ b ^ c) != 0) ? 1 : 0;
                if (by_search != by_xor) agree = 0;
                if (!by_search) losing++;
                checked++;
            }
        }
    }
    printf("Bouton's theorem vs exhaustive search: %d positions checked\n", checked);
    printf("theorem and search agree everywhere: %s\n", agree ? "YES" : "NO!");
    printf("losing positions found: %d (every one has XOR = 0)\n", losing);

    printf("__NB_SET__ {\"key\":\"nim_theory\",\"value\":{\"subGrundy\":[");
    for (int n = 0; n <= 20; n++) printf(n ? ",%d" : "%d", sub_grundy[n]);
    printf("],\"checked\":%d,\"agree\":%s,\"losing\":%d}}\n",
           checked, agree ? "true" : "false", losing);
    return 0;
}

// Independent audit of the C results.
const t = nb.get('nim_theory');
if (!t) return 'Run the C cell first.';

const patternHolds = t.subGrundy.every((g, n) => g === n % 4);
console.log('subtraction-game grundy matches n mod 4:', patternHolds);
console.log('C checked', t.checked, 'nim positions; theorem agreed:', t.agree);

// count XOR-zero positions independently: for a,b in 0..8, c is forced (a^b),
// and is valid when a^b <= 8
let xorZero = 0;
for (let a = 0; a < 9; a++)
  for (let b = 0; b < 9; b++)
    if ((a ^ b) < 9) xorZero++;
console.log('positions with a^b^c == 0 by counting:', xorZero,
  '- matches C search:', xorZero === t.losing);

return {
  grundyPattern: patternHolds,
  boutonVerified: t.agree && xorZero === t.losing,
  advice: 'always move to XOR 0 - the game below punishes anything else',
};
